// 吉祥物融進介面：從卡片或照片的上緣探頭（2026-11-13 第四段之二）。
// Yolin 看了第四段第一版的截圖：「我要的吉祥物整合是像這樣，角色融入到按鍵或畫面裡，不是像現在角色站在文字旁邊，
// 甚至沒有去背」。第一版是六張 240×240 的圓角小卡、自帶底色，放在字的旁邊；這一版改成：
//   - **沒有底色**：只有角色和它手上的東西，其餘透明（scripts/arttransparenttest.mjs 把每一張真的畫出來量，鋪滿就紅）。
//   - **對在畫面元素的上緣**：每一張都有一條邊線；畫面上那張卡片（天氣頁的出門提醒卡）或那張照片（完成任務）的
//     上緣就對在這條線上。邊線以下的身體不畫——被卡片擋住，像從卡片後面探出頭來；手掌扣在邊上、碗和相機擱在邊上、
//     雪板踩在邊上。掛到卡片上用 ui.js 的 mountPeek。
// 角色本身跟 glyphs.js 的吉祥物同一套畫法（第 6 版的函式，姿勢與道具另擺；產圖時比對過六隻基本姿勢跟 glyphs.js 相同）；
// 原創性的檢查見 docs/吉祥物原創性檢查.md。
//
// **只在有把握的時候出場**（設計原則：猜出來的東西不准變成使用者看得到的）：
//   - 完成任務：只看內建景點庫的資料——必吃清單與策展的「吃」類任務、景點的可信類別（theme.js 的 trustedTheme，
//     不看存著的 spot.theme）。自己打字的地點、類別拿不到的：小鳳打領結（已上線那一隻）從照片上緣探頭。
//   - 天氣：只看 Open-Meteo 的預報數字，跟「出門提醒」同一條下雨／下雪規則（weather.js 的 isRainDay／isSnowDay）。
//
// 這支檔用到時才載入（dynamic import）：圖不放進每一頁都要載的 glyphs.js。
// 一律 aria-hidden、圖裡沒有字；意思由旁邊的字講（慶祝的標題、天氣提示的句子）。輸入全是本檔的常數字串。
import { reducedMotion, pivotWrap, wrapPart } from './glyphs.js';

const NS = 'http://www.w3.org/2000/svg';
let seq = 0;

// 天氣：那一天會下雨／下雪 → 哪一張
export const WEATHER_PEEK = Object.freeze({ rain: 'rain', snow: 'snow' });
// 完成任務：景點庫那一筆的類型 → 哪一張（沒列的類型＝沒有對得上的圖 → DONE_PEEK）
// v1.94.0 以前看的是可信類別（THEME_PEEK：food／nightmarket／nature／urban）。打卡在 data/themes.json 改成中性
// （Dispatch 2026-11-16「打卡改成中性、不顯示主題小標」）之後，沒有任何類型會換成 urban，相機那張就再也不會出現；
// Dispatch 2026-11-17 定丙：類別改中性，探頭圖改看景點庫的類型（trustedTheme 回傳的 cat），打卡照樣是相機。
// 這張表跟舊的逐項一樣（舊：類型 →〔themes.json 的 byTag〕→ 類別 →〔THEME_PEEK〕→ 圖；food、snack → food → eat；
// nightmarket → grill；nature、view → nature → hat；checkin → urban → cam；culture、shopping、sight 沒有圖）——v1.94.0 用一次性腳本
// 拿舊版程式逐筆比過景點庫每一筆（結果記在 STATUS）。
export const CAT_PEEK = Object.freeze({
  food: 'eat',          // 美食：小鳳圍著圍兜捧一碗麵
  snack: 'eat',         // 小吃：同上
  nightmarket: 'grill', // 夜市：北北綁頭巾舉烤串
  nature: 'hat',        // 自然（山、島、溫泉街）：北北戴遮陽帽揮手——不畫成健行，免得跟一大半對不上
  view: 'hat',          // 觀景台：同上
  checkin: 'cam',       // 打卡：鬍鬍把相機擱在照片上（拿相機拍照本來就是「打卡」的意思，跟都不都市無關）
});
export const DONE_PEEK = 'done';

// 一站的探頭圖：v 是 theme.js 的 trustedTheme(spot, lookup) 回傳值。複核通過、類型在表上 → 那一張；其餘 → null（呼叫端自己決定退回哪一張）。
// 收的是回傳值、不自己呼叫 trustedTheme：這支檔用到時才載入，不為了這一行多 import 一支檔。
// 「複核通過才算」靠 cat：trustedTheme 只在複核通過時寫 cat，其餘一律 null（themetrusttest R1、R2、R5、R8 驗）——這裡不再另看 recheck，
// 免得兩道守同一件事、拿掉一道不會有測試紅。
// 用 hasOwnProperty：cat 是景點庫的字串，'toString' 這種物件本來就有的名字不准對到東西。
export function peekForVerdict(v) {
  if (!v || typeof v.cat !== 'string') return null;
  return Object.prototype.hasOwnProperty.call(CAT_PEEK, v.cat) ? CAT_PEEK[v.cat] : null;
}

// 深色主題的白邊：跟 glyphs.js 的吉祥物同一個濾鏡（和紙主題由 CSS 關掉：html[data-theme="washi"] .gl-peek .mc-fig）。
// 只有範圍不一樣：這裡用整張圖的座標（userSpaceOnUse）、四邊各多留 30——裁切框（peek() 裡的 -up／-dn）只到 20，
// 再多一個白邊的寬度（5）以上，看得到的那一塊不管畫到哪裡，白邊都不會被範圍切掉。
// 不能照 glyphs.js 寫「那一塊的外框 ±15%」：邊線以下那一層只有手掌、碗腳這種小東西，外框的 15% 不到 5 個單位，
// 白邊被範圍切成直角，深色下照片上多一塊白色方塊（2026-11-13 截圖抓到；peektest 深色那輪量範圍罩不罩得住）。
function rimDefs(id, [x, y, w, h]) {
  return `<defs><filter id="${id}" filterUnits="userSpaceOnUse" x="${x - 30}" y="${y - 30}" width="${w + 60}" height="${h + 60}">`
    + '<feMorphology in="SourceAlpha" operator="dilate" radius="5" result="d"/><feFlood flood-color="#ffffff"/>'
    + '<feComposite in2="d" operator="in" result="w"/>'
    + '<feMerge><feMergeNode in="w"/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs>';
}

// 一張探頭圖。k＝每一個畫布單位畫成幾 px（天氣卡約 0.34、照片約 0.6）。
//   k 是顯示縮放、不是身體比例：看那張卡／照片多大挑的畫面大小（當時沒留算式），跟參考圖的量測無關。
//   推送前的參考數字掃描會撞到天氣卡那個值（還有畫布座標裡湊出來的同一串數字），是巧合；
//   2026-11-13 Dispatch 看過、判定照用，不必為了掃描改值。
// 回傳 <svg class="gl-peek">；CSS 用 --pk-sink（邊線離圖底幾 px）把邊線對在父元素的上緣：
//   父元素 position: relative；.gl-peek { position: absolute; bottom: calc(100% - var(--pk-sink)); }
// 圖分三層：
//   上層＝邊線以上：身體＋前景一起套深色白邊（白邊在邊線處被裁掉，才不會在卡片上留一條白帶）；
//   動作線、蒸氣、閃光（mc-extra）：跟 glyphs.js 同一條規矩，只在和紙畫、不套白邊（深色由 CSS 藏起來）；
//   下層＝邊線以下（往上多蓋 1 個單位，理由見裁切框那裡）：只有前景（手掌下半、碗腳），自己套白邊。
export function peek(kind, k = 0.6) {
  const p = PEEK[kind];
  if (!p) throw new Error('沒有這張探頭圖：' + kind);
  const n = ++seq, id = `pk${n}`;
  const [x, y, w, h] = p.vb, e = p.edge;
  const el = document.createElementNS(NS, 'svg');
  el.setAttribute('viewBox', p.vb.join(' '));
  el.setAttribute('width', (w * k).toFixed(1));
  el.setAttribute('height', (h * k).toFixed(1));
  el.setAttribute('aria-hidden', 'true');
  el.setAttribute('focusable', 'false');
  el.setAttribute('class', `gl-peek pk-${kind}`);
  el.setAttribute('data-peek', kind);
  el.style.setProperty('--pk-sink', `${((y + h - e) * k).toFixed(1)}px`);
  el.style.setProperty('--pk-rise', `${((e - y) * k).toFixed(1)}px`);   // 邊線以上有多高（卡片上面要留這麼多空間，見 ui.js 的 mountPeek）
  // 圖裡的 id（裁切框）是 i0、i1…，每一張加上自己的流水號：同一頁好幾張時引用才不會指到別張
  // 前景（front）上下兩層各畫一次：下層那一份換另一個前綴（pkNd-），前景裡有裁切框的（新姿勢的鬍鬍揮手、山雀坐姿）id 才不會在同一張圖裡出現兩次
  // （2026-11-18 A 場 peektest P8、mascottest M8 設定頁抓到 pk5-i1 重複）。
  const pre = (s, tag = id) => s.replace(/(\bid="|url\(#)(i\d+)(?=[")])/g, `$1${tag}-$2`);
  const flt = ` filter="url(#${id}-rim)"`;
  el.innerHTML = rimDefs(`${id}-rim`, p.vb)
    + `<defs><clipPath id="${id}-up"><rect x="${x - 20}" y="${y - 20}" width="${w + 40}" height="${e - y + 20}"/></clipPath>`
    // 下層往上多蓋 1 個單位：兩層剛好在邊線交接的話，那一列兩邊的抗鋸齒各蓋一半，手掌、相機上會透出一條淡淡的亮線
    // （2026-11-13 放大截圖看到）。多蓋的那一條在上層裡本來就有同樣的前景與白邊，看不出差別。
    + `<clipPath id="${id}-dn"><rect x="${x - 20}" y="${e - 1}" width="${w + 40}" height="${y + h - e + 21}"/></clipPath></defs>`
    + `<g clip-path="url(#${id}-up)"><g class="mc-fig"${flt}>${pre(p.fig)}${pre(p.front)}</g>`
    + (p.extra ? `<g class="mc-extra">${pre(p.extra)}</g>` : '') + '</g>'
    + (p.front ? `<g clip-path="url(#${id}-dn)"><g class="mc-fig"${flt}>${pre(p.front, `${id}d`)}</g></g>` : '');
  return el;
}

// 新姿勢（Yolin 2026-11-18 晚上看了第一版截圖：「我覺得這版不行，嘗試用 GPT 生成的新姿勢圖做看看」；要比第一版大、顯眼、
// 跟卡片按鈕有互動、動作明顯，但不擋操作、不蓋字）：融入九宮格照著畫成向量的 9 張（hi／purse／hello／perch／puzzle／board／
// scout／point／star，docs/DESIGN_吉祥物融入介面.md 6.2）全部用同一個縮放。
// 不照「邊線以上多高」對齊（peekFit 那種）：耳朵、頭冠、毛帽高低差很多，對齊高度會變成頭不一樣大；
// 畫布單位跟 glyphs.js 的全身圖同比例，同一個縮放頭就一樣大。
// 0.6＝跟完成任務照片上那張同一個縮放（第一版放在按鈕、卡片上的是 0.3～0.4）。
// 邊線以下（手、道具、尾巴）每一張最多 20 個畫布單位＝12px：卡片、按鈕的字不被蓋到（產圖時的規矩）。
// 阿灰（scout／point）頭頂的深灰帶、白下巴、point 伸出去那隻翅膀的深色翅尖，都直接畫成算好的形狀
// （頭形 ∩ 帶子、頭形 ∩ 下巴橢圓、翅膀形 ∩ 長方形），不用 clipPath 裁：
// 2026-11-18 在 Chromium 實測：scout 的頭轉了 3°，頭頂那條帶子用 <path> 形的 clipPath 裁，被裁成那條 path 的外接長方形
// （拿掉旋轉就裁對）；point 的翅尖（轉 -108°，也是 <path> 形的 clipPath）不套 CSS 時一樣裁錯，在 App 裡剛好裁對（原因沒查到）。
// clipPath 裡是 <ellipse> 的，轉了角度也裁對。Yolin：「阿灰頭上有一塊灰色長方形」。照規格裁的 librsvg（sharp）畫出來是對的，
// 所以只看 sharp 的圖看不出來。算好的形狀跟照規格裁的逐畫素相同（8 倍放大比 0 畫素不同）。
// 新畫的圖別把 path 形的 clipPath 放進轉過角度的群組裡（scripts/cliptest.mjs 擋這種寫法）。
export const POSE_K = 0.6;
// 置中掛（.pose-c）時對齊宿主中線的是「身體中線」、不是圖框中間（v1.96.0）：
// 揮手的鬍鬍（hello）圖框裡含舉起的手與揮動線，圖框中間在 x 120、身體中線在 100（鼻子 cx 100），
// 照圖框置中，身體在按鈕中線左邊 20 單位＝12px——Yolin 2026-11-19 回報底部分頁「照片」那格的鬍鬍偏左，Dispatch 要照片空白頁這隻一起量、偏就修。
// 指路阿灰（point）：圖框裡含伸出去指路的那隻翅膀，圖框中間 113、身體中線 100（身體 path 對 100 對稱）→ 沒登記時身體在左 7.8px。
// Dispatch 2026-11-19 08:2x：阿灰這版一起對準。沒登記的照圖框置中（--pk-dx 0）。scripts/tabicontest.mjs TI13～TI17 在瀏覽器裡量。
// 搔頭湯圓（puzzle，邀請讀不到）刻意不登記：整個身體繞 (100,170) 轉了 12°（歪頭），剪影沒有左右對稱的中線；深色主題描的白邊
//   又把量到的鏡射軸推右 5 個畫布單位（同一個位置和紙量到右 1.33px、深色右 4.83px）——沒有一個量法在兩個主題都量得準，
//   證明不了「對準」。Dispatch 2026-11-19 選甲：維持照圖框置中（v1.96.0 之前的樣子）。要登記牠，先找到兩個主題一致的量法。
const POSE_MID = Object.freeze({ hello: 100, point: 100 });
// side＝掛在宿主的哪一邊（CSS .pose-l／.pose-r／.pose-c）；宿主上面要留的空間由 ui.js 的 mountPose 處理。
export function pose(kind, side = 'r') {
  const el = peek(kind, POSE_K);
  el.classList.add('pose', `pose-${side}`);
  const mid = POSE_MID[kind];
  if (side === 'c' && mid != null) {
    const [x, , w] = PEEK[kind].vb;
    el.style.setProperty('--pk-dx', `${((x + w / 2 - mid) * POSE_K).toFixed(1)}px`);   // 往右挪多少，身體中線才落在宿主中線
  }
  return el;
}

// 行程海報（v1.89）用的那一張：海報上沒有卡片蓋在前面、也不套白邊（米色紙底，跟和紙主題一樣），所以不必分上下兩層——
// 身體照樣在邊線裁掉（邊線以下本來藏在卡片後面，畫出來會蓋到框），前景（手掌、碗腳）一整塊畫、不裁。
// 分兩層畫的話，下層裁切框的上緣那一列會在手掌的深色外框上透出一條淡線（2026-11-14 放大海報看到，海報上一個單位約 2 px，
// 上面那 1 個單位的重疊蓋不住）。層的順序跟 peek() 一樣：身體、前景、動作線。
export function peekFlat(kind, k = 1) {
  const p = PEEK[kind];
  if (!p) throw new Error('沒有這張探頭圖：' + kind);
  const id = 'pf' + (++seq);   // 海報每一隻各自轉成一張圖，id 不會撞；照樣每張不同（跟 peek() 同一個流水號）
  const [x, y, w, h] = p.vb, e = p.edge;
  const el = document.createElementNS(NS, 'svg');
  el.setAttribute('viewBox', p.vb.join(' '));
  el.setAttribute('width', (w * k).toFixed(1));
  el.setAttribute('height', (h * k).toFixed(1));
  el.setAttribute('data-peek', kind);
  const pre = (s) => s.replace(/(\bid="|url\(#)(i\d+)(?=[")])/g, `$1${id}-$2`);
  const up = `clip-path="url(#${id}-up)"`;
  el.innerHTML = `<defs><clipPath id="${id}-up"><rect x="${x - 20}" y="${y - 20}" width="${w + 40}" height="${e - y + 20}"/></clipPath></defs>`
    + `<g class="mc-body" ${up}>${pre(p.fig)}</g>`
    + (p.front ? `<g class="mc-front">${pre(p.front)}</g>` : '')
    + (p.extra ? `<g class="mc-extra" ${up}>${pre(p.extra)}</g>` : '');
  return el;
}

// 一張圖的尺寸（畫布單位）：寬、邊線以上多高（rise）、邊線以下多深（sink）。
// 行程海報（v1.89）每天一隻探頭：排版那支（js/itinposter/layout.js）是純函式、不碰 DOM，先拿這個算出圖要佔多大、
// 邊線以下的手掌會伸進框裡多深，排好再交給 js/itinposter/draw.js 用 peek() 畫。
export function peekGeom(kind) {
  const p = PEEK[kind];
  if (!p) throw new Error('沒有這張探頭圖：' + kind);
  const [, y, w, h] = p.vb;
  return { w, rise: p.edge - y, sink: y + h - p.edge };
}

// 畫成「邊線以上剛好 px 高」的那一張（v1.87.1 主頁下雨／下雪那一句：跟原本站在對話框左邊那一隻一樣高）。
// 縮放照這一張自己的畫布算，不另外寫一個數字——每一張邊線以上的高度不同（撐傘那一張比踩雪板那一張矮）。
export function peekFit(kind, px) {
  const p = PEEK[kind];
  if (!p) throw new Error('沒有這張探頭圖：' + kind);
  return peek(kind, px / (p.edge - p.vb[1]));
}

// 探頭圖的動作：先從卡片／照片後面跳上來，再做這一張自己的動作。
// v1.83.0 只有完成任務那一刻的小鳳打領結（Yolin 看了實機：「效果不錯，推廣到其他時刻」）；v1.85.0 推廣到每一張（核過的那張表）。
// 在哪裡呼叫：完成任務的慶祝畫面（js/addphoto.js，五張之一）、天氣頁的出門提醒卡（js/views/weather.js，下雨／下雪）、
// 主頁「旅程結束了」「任務全部完成了」那張卡（js/views/trip.js，小鳳打領結）。
// 測試：scripts/peektest.mjs 的「動畫」那幾條（每一張有動、跳之前整隻藏在後面、只動 transform／opacity、停在靜止圖的位置、減少動態效果時不動）。
//   parts＝會動的零件：tf＝那個零件每一段共用的 transform 字串（見 glyphs.js 的 wrapPart）；sel＝整個群組（沒有 transform 屬性的，例如煙那一層）；
//          pivot＝轉的原點（肩膀、握著的那隻手）；cls＝哪一種動作（css/style.css）
//   extra＝動作線那一層（.mc-extra：揮動線、蒸氣、閃光，只在和紙畫）加的動作；slide＝整隻左右滑一下
// 零件對不上（圖改過）就只跳上來、那個零件不動——寧可少動，也不要動錯地方（那張表：「零件拆不出來就只做跳上來」）。
const CHEER = Object.freeze({
  // 小鳳打領結：揮翅膀（翅膀外框、底色、亮面、羽毛線四段分開畫）
  done: { parts: [{ tf: 'translate(70 146) rotate(122)', pivot: [70, 146], cls: 'pk-wave' }], extra: 'pk-wave-lines' },
  // 小鳳捧麵：碗上的蒸氣淡入淡出
  eat: { extra: 'pk-steam' },
  // 北北烤串：烤串繞握著它的那隻手左右晃兩下，串上冒的煙跟著晃（不然煙會跟串分開）
  grill: { parts: [{ tf: 'rotate(-28 49.82 134.24)', pivot: [49.82, 134.24], cls: 'pk-sway' }, { sel: '.mc-extra', pivot: [49.82, 134.24], cls: 'pk-sway' }] },
  // 北北戴帽：舉起來的那隻手（右手，角度跟小鳳的翅膀鏡像）揮兩下
  hat: { parts: [{ tf: 'translate(134 146) rotate(-122)', pivot: [134, 146], cls: 'pk-wave-r' }], extra: 'pk-wave-lines' },
  // 鬍鬍：相機閃一下
  cam: { extra: 'pk-flash' },
  // 鬍鬍撐傘：傘繞握著傘柄的那隻手（扣在卡片上緣，156,150）輕輕晃
  rain: { parts: [{ tf: 'translate(139.96 137.16)', pivot: [139.96, 137.16], cls: 'pk-tilt' }] },
  // 山雀踩雪板：整隻連雪板左右滑一下
  snow: { slide: true },
  /* POSE-CHEER-BEGIN */
  // 新姿勢的動作（零件與 class 是產圖時定的；錯誤狀態那一張 puzzle 一律靜止、不在這裡）
  hi: { parts: [{ tf: 'translate(66 148) rotate(150)', pivot: [66, 148], cls: 'pk-wave' }], extra: 'pk-wave-lines' },
  purse: { parts: [{ tf: 'translate(66 148) rotate(150)', pivot: [66, 148], cls: 'pk-wave' }, { tf: 'translate(134 122)', pivot: [134, 122], cls: 'pk-coin' }] },
  hello: { parts: [{ tf: 'translate(159.77 153.88)', pivot: [159.77, 153.88], cls: 'pk-wave-r' }], extra: 'pk-wave-lines' },
  perch: { parts: [{ tf: 'translate(60 144) rotate(34)', pivot: [60, 144], cls: 'pk-flap' }] },
  board: { parts: [{ tf: 'rotate(0 100 136)', pivot: [100, 136], cls: 'pk-sway' }] },
  scout: { parts: [{ tf: 'rotate(0 133 148)', pivot: [133, 148], cls: 'pk-scan' }], nod: true },
  point: { parts: [{ tf: 'translate(132 147) rotate(-108)', pivot: [132, 147], cls: 'pk-wave' }] },
  star: { parts: [{ tf: 'translate(96.23 145.72)', pivot: [96.23, 179.38], cls: 'pk-shine' }] },
  /* POSE-CHEER-END */
});
export const CHEER_KINDS = Object.freeze(Object.keys(CHEER));
// 把 peek() 做好的圖變成會動的版本；回傳有沒有動。減少動態效果（glyphs.js 的 reducedMotion）就不動，停在現在的靜止圖。
// soft：慢慢探上來、不回彈（天氣頁、主頁的卡片——那張表寫「探上來」）；沒給就是跳上來（完成任務那一刻）。
// still：不跳上來、零件平常的動作也不做，只做 add 指定的那一個（新姿勢：記帳存檔那一刻只把硬幣丟進錢包 pk-coin-go——
//   同一頁已經看過牠跳上來，不再跳一次）。圖裡那枚硬幣本身的 class 叫 pk-drop（平常透明），所以 add 不用這個名字。
// add：另外掛在 <svg> 上的 class（只准本檔與 css/style.css 寫好的那幾個，見 CSS 的 .pk-still 那一段）。
// 新姿勢的圖另外多包一層 .pk-nod（整隻繞邊線中間轉），給已經出場之後的動作用：建立行程被擋下時搖頭（nudge）。
export function cheer(el, { soft = false, still = false, add = [] } = {}) {
  if (reducedMotion()) return false;
  const kind = el.getAttribute('data-peek'), c = CHEER[kind], p = PEEK[kind];
  if (!c || !p) return false;
  const [up, dn] = el.querySelectorAll(':scope > g[clip-path]');
  if (!up) return false;
  const wrapKids = (host, cls) => { const w = document.createElementNS(NS, 'g'); w.setAttribute('class', cls); w.append(...host.childNodes); host.append(w); return w; };
  for (const q of c.parts || []) {
    if (q.sel) { const x = up.querySelector(q.sel); if (x) pivotWrap(x, q.pivot, q.cls); }
    else wrapPart(up, q.tf, q.pivot, q.cls);
  }
  if (c.extra) up.querySelector('.mc-extra')?.classList.add(c.extra);
  const hop = wrapKids(up, 'pk-hop');
  if (c.slide) wrapKids(hop, 'pk-slide');   // 跳（探）上來那一層裡面再包一層左右滑：兩個動作各自一層，互不覆蓋
  if (c.nod) {
    // 搖頭那一層：轉的原點在邊線的中間（整隻像從卡片後面左右擺頭）；跟跳上來、左右滑各自一層，互不覆蓋
    const host = hop.querySelector(':scope > .pk-slide') || hop;
    const kids = [...host.childNodes];
    const nod = pivotWrap(document.createElementNS(NS, 'g'), [p.vb[0] + p.vb[2] / 2, p.edge], 'pk-nod');
    host.append(nod.parentNode);
    nod.firstChild.replaceChildren(...kids);
  }
  if (dn) wrapKids(dn, 'pk-grip');
  // 起跳點：邊線以上的畫布有 (edge − 畫布頂) 個單位高，再往下多 8（外框線、深色的白邊），整隻藏在卡片／照片後面才開始跳。
  // v1.83.0 只有一張，寫死在 CSS（176）；現在每一張高度不同（120～194），由這裡照圖算、CSS 的 keyframes 讀 --pk-from。
  el.style.setProperty('--pk-from', `${p.edge - p.vb[1] + 8}px`);
  el.classList.add('pk-cheer');
  if (soft) el.classList.add('pk-soft');
  if (still) el.classList.add('pk-still');
  for (const a of add) if (CHEER_ADD.includes(a)) el.classList.add(a);
  return true;
}
// cheer() 的 add 只准這幾個（CSS 有寫的）：寫錯名字就是什麼都不動，不如不收
const CHEER_ADD = Object.freeze(['pk-coin-go']);

// 已經出場（cheer 過）的那一張再做一次動作：建立行程沒填名稱被擋下 → 搖頭（pk-shake，動 .pk-nod 那一層）。
// 先拿掉再加回去，連按兩次也會再搖一次。沒 cheer 過（減少動態效果、圖對不上）就不動，回傳 false。
export function nudge(el, cls = 'pk-shake') {
  if (!el || !el.classList.contains('pk-cheer') || !el.querySelector('.pk-nod')) return false;
  el.classList.remove(cls);
  void el.getBoundingClientRect();   // 讓瀏覽器先算一次沒有這個 class 的樣子，加回去動畫才會從頭開始
  el.classList.add(cls);
  return true;
}
// 等待中一直重複的動作（建立行程「產生中…」：阿灰一直舉起望遠鏡看——pk-scan 的重複版，跟載入中同一個意思，只有等待會重複）。on＝false 停回靜止圖。
export function busy(el, on) {
  if (!el || !el.classList.contains('pk-cheer')) return false;
  el.classList.toggle('pk-busy', !!on);
  return true;
}

// 完成任務的慶祝畫面放哪一張（一定有一張：沒把握就是 DONE_PEEK）
// 「吃東西」只認兩種任務：必吃清單（景點庫裡的真的菜名）、策展的「吃」類任務。不看範本任務的 kind——
// 夜市主題的範本任務 kind 也是 food，但題目多半是「拍最有氣勢的攤位」「人潮的縱深」，不是在吃；那些照景點類別走（夜市＝烤串）。
export async function completionPeekKind(quest, spot) {
  if (!spot || spot.source !== 'curated') return DONE_PEEK;      // 自己打字的地點：沒有可信的類別
  if (quest && (quest.source === 'must' || (quest.source === 'curated' && quest.kind === 'food'))) return CAT_PEEK.food;
  const [{ loadPlaceLookup }, th] = await Promise.all([import('./quests/generate.js'), import('./theme.js')]);
  await th.loadThemes();
  return peekForVerdict(th.trustedTheme(spot, await loadPlaceLookup())) || DONE_PEEK;
}

